// src/components/Stats.js
import React from 'react';

// A reusable card component for displaying a single statistic.
const StatCard = ({ title, count, bgColor, textColor }) => (
  <div className={`flex-1 p-6 rounded-xl shadow-sm ${bgColor}`}>
    <p className={`text-4xl font-bold ${textColor}`}>{count}</p>
    <p className="text-gray-600 mt-1">{title}</p>
  </div>
);

function Stats({ total, completed, incomplete }) {
  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <div className="flex flex-col sm:flex-row gap-4">
        <StatCard 
          title="Total Tasks" 
          count={total} 
          bgColor="bg-blue-50" 
          textColor="text-blue-600" 
        />
        <StatCard 
          title="Completed" 
          count={completed} 
          bgColor="bg-green-50" 
          textColor="text-green-600" 
        />
        <StatCard 
          title="Incomplete" 
          count={incomplete} 
          bgColor="bg-orange-50" 
          textColor="text-orange-600" 
        />
      </div>
    </div>
  );
}

export default Stats;
